import{_ as a,o as s,c as n,a4 as d}from"./chunks/framework.vNSRaLQv.js";const S=JSON.parse('{"title":"USB 设备共享协议折腾记录","description":"","frontmatter":{"title":"USB 设备共享协议折腾记录","date":"2026-07-11T00:00:00.000Z"},"headers":[],"relativePath":"posts/USB协议折腾记录.md","filePath":"posts/USB协议折腾记录.md"}'),r={name:"posts/USB协议折腾记录.md"};function i(l,t,o,e,h,p){return s(),n("div",null,[...t[0]||(t[0]=[d(`<h1 id="usb-设备共享协议折腾记录" tabindex="-1">USB 设备共享协议折腾记录 <a class="header-anchor" href="#usb-设备共享协议折腾记录" aria-label="Permalink to &quot;USB 设备共享协议折腾记录&quot;">​</a></h1><blockquote><p>设备：Xiaomi R3 (Mi Router 3) / PandoraBox 19.01 / MT7620 MIPS / 128MB RAM U 盘：Intel Optane 傲腾 USB / 13.4GB (ext4) 网络：Wi-Fi WISP 中继 + 100Mbps LAN</p></blockquote><hr><h2 id="一、试过的协议总览" tabindex="-1">一、试过的协议总览 <a class="header-anchor" href="#一、试过的协议总览" aria-label="Permalink to &quot;一、试过的协议总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>协议</th><th>服务器</th><th>Windows 客户端</th><th>服务器开销</th><th>安装难度</th></tr></thead><tbody><tr><td><strong>Samba (SMB)</strong></td><td>PandoraBox 自带</td><td>内置，零安装</td><td>~11MB 进程</td><td>自带</td></tr><tr><td><strong>NFS v3 (unfs3)</strong></td><td>opkg 安装</td><td>需第三方（家庭版无内置）</td><td>~8MB 进程</td><td>简单</td></tr><tr><td><strong>FTP (vsftpd)</strong></td><td>opkg 安装</td><td>不能挂盘符</td><td>轻</td><td>简单</td></tr><tr><td><strong>WebDAV</strong></td><td>需装 lighttpd</td><td>能映射但不稳</td><td>轻</td><td>复杂</td></tr><tr><td><strong>iSCSI (tgt)</strong></td><td>opkg 安装</td><td><strong>内置，家庭版也有</strong></td><td>~1MB + 133KB</td><td>简单</td></tr><tr><td><strong>SFTP (sshfs)</strong></td><td>Dropbear+openssh-sftp</td><td>SSHFS-Win (开源)</td><td>轻</td><td>中等</td></tr></tbody></table><hr><h2 id="二、实测性能对比" tabindex="-1">二、实测性能对比 <a class="header-anchor" href="#二、实测性能对比" aria-label="Permalink to &quot;二、实测性能对比&quot;">​</a></h2><h3 id="顺序读写-网络-samba-iscsi" tabindex="-1">顺序读写 (网络 Samba/iSCSI) <a class="header-anchor" href="#顺序读写-网络-samba-iscsi" aria-label="Permalink to &quot;顺序读写 (网络 Samba/iSCSI)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>测试项</th><th>Samba</th><th>iSCSI (tgt)</th><th>提升</th></tr></thead><tbody><tr><td>顺序写入 (50MB)</td><td><strong>9.7 MB/s</strong></td><td><strong>14.6 MB/s</strong></td><td><strong>+50%</strong></td></tr><tr><td>顺序读取 (50MB)</td><td>24.2 MB/s</td><td>~308 MB/s*</td><td>缓存加速</td></tr></tbody></table><h3 id="_4k-随机读写-碎文件场景" tabindex="-1">4K 随机读写 (碎文件场景) <a class="header-anchor" href="#_4k-随机读写-碎文件场景" aria-label="Permalink to &quot;4K 随机读写 (碎文件场景)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>测试项</th><th>Samba</th><th>iSCSI (tgt)</th><th>提升</th></tr></thead><tbody><tr><td>4K随机写入</td><td>571 IOPS (2.23MB/s)</td><td>79 IOPS (0.31MB/s)</td><td>❌ 数据异常</td></tr><tr><td>4K随机读取</td><td>420 IOPS (1.64MB/s)</td><td><strong>658 IOPS (2.57MB/s)</strong></td><td><strong>+57%</strong></td></tr></tbody></table><h3 id="路由器本地-dd-测速-不经过网络" tabindex="-1">路由器本地 dd 测速 (不经过网络) <a class="header-anchor" href="#路由器本地-dd-测速-不经过网络" aria-label="Permalink to &quot;路由器本地 dd 测速 (不经过网络)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>测试项</th><th>速度</th></tr></thead><tbody><tr><td>顺序写入 (U盘)</td><td>25.3 MB/s</td></tr><tr><td>顺序读取 (U盘)</td><td>31.1 MB/s</td></tr><tr><td>4K 随机写入</td><td>20.0 MB/s (5000 IOPS)</td></tr><tr><td>4K 随机读取</td><td><strong>40.0 MB/s (10000 IOPS)</strong> ← 傲腾真实力</td></tr></tbody></table><hr><h2 id="三、各协议优缺点" tabindex="-1">三、各协议优缺点 <a class="header-anchor" href="#三、各协议优缺点" aria-label="Permalink to &quot;三、各协议优缺点&quot;">​</a></h2><h3 id="_1-samba-smb" tabindex="-1">1. Samba (SMB) <a class="header-anchor" href="#_1-samba-smb" aria-label="Permalink to &quot;1. Samba (SMB)&quot;">​</a></h3><ul><li><strong>优点：</strong> Windows 原生支持，零安装，全屋共享，手机/电视/游戏机都能用</li><li><strong>缺点：</strong> MIPS CPU 负担重，4K 碎文件慢（420 IOPS），协议开销大</li><li><strong>结论：</strong> ✅ 最通用，全屋共享唯一可行方案</li></ul><h3 id="_2-nfs-v3-unfs3" tabindex="-1">2. NFS v3 (unfs3) <a class="header-anchor" href="#_2-nfs-v3-unfs3" aria-label="Permalink to &quot;2. NFS v3 (unfs3)&quot;">​</a></h3><ul><li><strong>优点：</strong> 服务器轻量（~8MB），4K 性能略好于 Samba</li><li><strong>缺点：</strong> Windows 家庭版无内置 NFS 客户端，第三方都需要注册/折腾</li><li><strong>结论：</strong> ❌ Windows 家庭版劝退</li></ul><h3 id="_3-ftp-vsftpd" tabindex="-1">3. FTP (vsftpd) <a class="header-anchor" href="#_3-ftp-vsftpd" aria-label="Permalink to &quot;3. FTP (vsftpd)&quot;">​</a></h3><ul><li><strong>优点：</strong> 极轻量</li><li><strong>缺点：</strong> Windows 不能挂盘符，不适合日常使用</li><li><strong>结论：</strong> ❌ 不适合此场景</li></ul><h3 id="_4-webdav" tabindex="-1">4. WebDAV <a class="header-anchor" href="#_4-webdav" aria-label="Permalink to &quot;4. WebDAV&quot;">​</a></h3><ul><li><strong>优点：</strong> Windows 可映射</li><li><strong>缺点：</strong> 服务器没装，HTTP 协议碎文件更差</li><li><strong>结论：</strong> ❌ 不如 Samba</li></ul><h3 id="_5-iscsi-tgt-⭐-推荐" tabindex="-1">5. iSCSI (tgt) ⭐ 推荐 <a class="header-anchor" href="#_5-iscsi-tgt-⭐-推荐" aria-label="Permalink to &quot;5. iSCSI (tgt) ⭐ 推荐&quot;">​</a></h3><ul><li><strong>优点：</strong><ul><li>块级协议，性能最好（658 IOPS 4K随机读）</li><li>Windows 所有版本内置 iSCSI 发起程序</li><li>服务器极轻量（tgt 133KB + 内核模块）</li><li>挂载后是本地磁盘，体验最好</li></ul></li><li><strong>缺点：</strong><ul><li>一次只能一台电脑挂载（不能全屋共享）</li><li>需要格式化为 NTFS</li></ul></li><li><strong>结论：</strong> ✅ <strong>单机最佳选择</strong></li></ul><h3 id="_6-sftp-sshfs" tabindex="-1">6. SFTP (SSHFS) <a class="header-anchor" href="#_6-sftp-sshfs" aria-label="Permalink to &quot;6. SFTP (SSHFS)&quot;">​</a></h3><ul><li><strong>优点：</strong> 开源，基于 SSH</li><li><strong>缺点：</strong> SSH 加密开销大，4K 比 Samba 还慢</li><li><strong>结论：</strong> ❌ 慢</li></ul><hr><h2 id="四、最终部署方案" tabindex="-1">四、最终部署方案 <a class="header-anchor" href="#四、最终部署方案" aria-label="Permalink to &quot;四、最终部署方案&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────┐</span></span>
<span class="line"><span>│             路由器               │</span></span>
<span class="line"><span>│  Xiaomi R3 / PandoraBox 19.01   │</span></span>
<span class="line"><span>│                                 │</span></span>
<span class="line"><span>│  ┌──── Samba (SMB) ────┐        │</span></span>
<span class="line"><span>│  │  全屋设备共享        │        │</span></span>
<span class="line"><span>│  │  \\\\192.168.1.1\\sda1 │        │</span></span>
<span class="line"><span>│  └─────────────────────┘        │</span></span>
<span class="line"><span>│                                 │</span></span>
<span class="line"><span>│  ┌─── iSCSI (tgt) ─────┐       │</span></span>
<span class="line"><span>│  │  单机高性能          │       │</span></span>
<span class="line"><span>│  │  iqn.2024-07.local   │       │</span></span>
<span class="line"><span>│  │  :cache:chrome       │       │</span></span>
<span class="line"><span>│  └─────────────────────┘        │</span></span>
<span class="line"><span>│                                 │</span></span>
<span class="line"><span>│       Intel Optane U盘 (ext4)    │</span></span>
<span class="line"><span>│       13.4GB                    │</span></span>
<span class="line"><span>└─────────────────────────────────┘</span></span></code></pre></div><ul><li><strong>多设备共享文件 → Samba</strong> （Windows 直接 \\192.168.1.1)</li><li><strong>单机需要高性能 → iSCSI</strong> （Windows iSCSI 发起程序连）</li><li><strong>U盘是傲腾</strong> → 读写寿命长，4K 随机读 10000 IOPS，但被路由器百兆口 + MIPS CPU 限制</li></ul><hr><h2 id="五、关键发现" tabindex="-1">五、关键发现 <a class="header-anchor" href="#五、关键发现" aria-label="Permalink to &quot;五、关键发现&quot;">​</a></h2><ol><li><strong>瓶颈在路由器，不在 U 盘</strong>：傲腾在路由器本地测 4K 读 40MB/s，经过 Samba 只剩 1.6MB/s，差了 25 倍</li><li><strong>iSCSI 比 Samba 快</strong>：块级协议，CPU 开销更小，顺序写 +50%，4K 读 +57%</li><li><strong>拉网线能到百兆上限 (~11MB/s)</strong>：现在走 Wi-Fi WISP 中继已经比百兆口快了（顺序读 24MB/s）</li><li><strong>这个路由器极限就在这了</strong>：580MHz MIPS + 128MB RAM + 百兆口，想更快只能换设备</li></ol>`,34)])])}const b=a(r,[["render",i]]);export{S as __pageData,b as default};
